+
+REXCVAR_DEFINE_DOUBLE(gh2_audiooffset, 0.0, "Guitar Hero 2", "Offset song audio to sync with notes");
+
+void GuitarHook(PPCRegister& r11) {
+    r11.u64 = 7;
