+void AudioOffsetHookPractice(PPCRegister& f1) {
+	double offset = static_cast<double>(REXCVAR_GET(gh2_audiooffset));
+	double newpos = f1.f64 + offset;
+	if (newpos < 0) return;
+	else f1.f64 = newpos;
